</template>
<script>
import DefaultPopup from "../defaultPopup.vue";
import Checkbox from "../Checkbox.vue";
import { mapGetters, mapActions } from "vuex";
export default {
	props: {},
	components: {
		DefaultPopup,
		Checkbox,
	},
	computed: {
		...mapGetters("PayAsYouGo", [
			"confirmationPopupConfig",
			"isCreditsConfirmationPopupVisible",
		]),
		getButtonClickFunction() {
			if (this.confirmationPopupConfig.buttonClickCB) {
				return this.confirmationPopupConfig.buttonClickCB.bind(
					null,
					this.doNotShowAgain
				);
			}

			return this.closeConfirmationPopupConfig;
		},
	},
	data: () => ({
		doNotShowAgain: true,
	}),
	watch: {
		// isCreditsConfirmationPopupVisible(nv) {
		// 	if (nv) {
		// 		this.doNotShowAgain = false;
		// 	}
		// },
	},
	mounted() {},
	methods: {
		...mapActions("PayAsYouGo", ["closeConfirmationPopupConfig"]),
		handleCheckboxChange(data) {
			this.doNotShowAgain = !this.doNotShowAgain;
		},
		getMessageString(item) {
			if (!this.$te(item, this.$i18n.locale)) {
				return item;
			} else {
				return this.$t(item);
			}
		},
	},
};
</script>
